const input = $input.first().json;
const body = input.body || input;

return [{
  json: {
    network: body.network || 'facebook',
    post_id: body.post_id || '',
    comment_id: body.comment_id || '',
    comment_text: body.comment_text || body.message || '',
    author_name: body.author_name || body.from?.name || '',
    author_id: body.author_id || body.from?.id || '',
    post_subject: body.post_subject || '',
    received_at: new Date().toISOString()
  }
}];

const response = $input.first().json;
const comment = $('Normaliser — Commentaire').first().json;

let parsed;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { sentiment: 'neutre', response: '', needs_human_review: true, suggested_action: 'escalate' };
}

return [{
  json: {
    ...comment,
    sentiment: parsed.sentiment,
    suggested_response: parsed.response,
    needs_human_review: parsed.needs_human_review,
    reason_for_review: parsed.reason_for_review || '',
    suggested_action: parsed.suggested_action
  }
}];
